def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    strong_prev = 0
    weak_urgent = 0
    rich_count = 0
    for opp in alive:
        if opp.get('budget', 0) >= 120:
            rich_count += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
            weak_urgent += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 90:
                strong_prev += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    my_urgent = hp <= 3 or no_water_days >= 2
    somewhat_urgent = hp <= 5 or no_water_days >= 1

    if supply <= 16:
        tightness = 'very_tight'
    elif supply <= 19:
        tightness = 'tight'
    elif supply <= 22:
        tightness = 'medium'
    else:
        tightness = 'loose'

    if my_urgent:
        base = max(92.0, highest_prev + 4.0, avg_prev + 8.0)
        if tightness == 'very_tight':
            base += 18.0
        elif tightness == 'tight':
            base += 10.0
        return float(min(budget, base))

    if tightness == 'very_tight':
        if strong_prev >= 2 or highest_prev >= 120:
            return float(min(budget, 18.0 if hp >= 6 else 55.0))
        base = max(40.0, avg_prev * 0.55)
        if somewhat_urgent:
            base = max(base, highest_prev + 2.0)
        return float(min(budget, base))

    if tightness == 'tight':
        if strong_prev >= 2 and hp >= 6 and no_water_days == 0:
            return float(min(budget, 24.0))
        base = max(38.0, avg_prev * 0.62)
        if weak_urgent >= 2:
            base += 8.0
        if somewhat_urgent:
            base = max(base, highest_prev + 1.5)
        return float(min(budget, base))

    if tightness == 'medium':
        base = max(42.0, avg_prev * 0.72)
        if weak_urgent >= 1:
            base += 10.0
        if rich_count >= 2 and highest_prev >= 100:
            base -= 6.0
        if somewhat_urgent:
            base += 8.0
        return float(min(budget, base))

    base = max(46.0, avg_prev * 0.78)
    if weak_urgent >= 1:
        base += 12.0
    if day >= 8 and hp >= 6 and budget > DAILY_SALARY * 2:
        base += 6.0
    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    # Fractional safety: convert to int for any indexing (none used), and for thresholds
    supply_int = int(round(supply))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents are alive, bid conservatively
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    prev_hp_after = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        try:
            prev_hp_after.append(float(prev.get('hp_after', 0.0)))
        except Exception:
            pass

    # Estimate competitive pressure from yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Determine our aggressiveness: if our hp is low, bid more.
    # Also, if yesterday we saw someone bidding high (Eric ~128), we slightly undercut.
    hp_factor = 1.0
    if hp <= 2.0:
        hp_factor = 1.25
    elif hp <= 4.0:
        hp_factor = 1.15
    elif hp >= 8.0:
        hp_factor = 0.95

    # Supply pressure: higher supply reduces need to overbid.
    # With our requirement 9, if supply is near 25, winning water is more likely without extreme bids.
    if supply_int >= 22:
        supply_factor = 0.92
    elif supply_int <= 17:
        supply_factor = 1.08
    else:
        supply_factor = 1.0

    # Core strategy: bid just above the typical survivor band (~100-110), but cap below highest_prev_bid.
    # If highest_prev_bid is very high, we undercut by aiming between second and highest.
    target = None
    if prev_bids:
        # Aim to beat the second-highest by a small margin, but not exceed highest_prev_bid.
        undercut = second_prev_bid + 3.0
        ceiling = highest_prev_bid - 2.0
        target = min(undercut, ceiling)

        # If our target is too low (e.g., no real bids), fallback.
        if target < DAILY_SALARY * 0.45:
            target = DAILY_SALARY * 0.55
    else:
        target = DAILY_SALARY * 0.55

    # Apply factors
    bid = target * hp_factor * supply_factor

    # Additional safety: if Cindy died with bid 0, others likely bid for survival; ensure not too low.
    if bid < DAILY_SALARY * 0.5:
        bid = DAILY_SALARY * 0.5

    # Never exceed budget
    if budget <= 0.0:
        return 0.0
    bid = max(0.0, min(bid, budget))

    # If we are extremely budget constrained, bid a fraction to preserve future options
    if budget < DAILY_SALARY * 0.6:
        bid = min(bid, budget * 0.9)

    return float(bid)
